/** One Bentrix endpoint, every capability of its catalogue under client.<domain>. */
class Bentrix extends Client {
  constructor(url, token, opts = {}) {
    super(url, token, { catalogueVersion: CATALOGUE_VERSION, ...opts });
    this.account = new AccountApi(this);
    this.accounts = new AccountsApi(this);
    this.agent = new AgentApi(this);
    this.alert = new AlertApi(this);
    this.alerts = new AlertsApi(this);
    this.bench = new BenchApi(this);
    this.catalogue = new CatalogueApi(this);
    this.chart = new ChartApi(this);
    this.data = new DataApi(this);
    this.drawing = new DrawingApi(this);
    this.drivers = new DriversApi(this);
    this.forecast = new ForecastApi(this);
    this.indicator = new IndicatorApi(this);
    this.laboratory = new LaboratoryApi(this);
    this.marketwatch = new MarketwatchApi(this);
    this.model = new ModelApi(this);
    this.output = new OutputApi(this);
    this.recordings = new RecordingsApi(this);
    this.replay = new ReplayApi(this);
    this.room = new RoomApi(this);
    this.settings = new SettingsApi(this);
    this.strategy = new StrategyApi(this);
    this.study = new StudyApi(this);
    this.template = new TemplateApi(this);
    this.trade = new TradeApi(this);
    this.trading = new TradingApi(this);
    this.workbench = new WorkbenchApi(this);
    this.workspace = new WorkspaceApi(this);
    this.zone = new ZoneApi(this);
  }
}

module.exports = { Bentrix, CATALOGUE_VERSION, CATALOGUE_DIGEST };
